import { useEffect } from 'react';

const Index = () => {
  useEffect(() => {
    // 懒加载首页配件组件（React.lazy 风格的原生 import()）
    import('../components/HomeExtra').then((m) => m.default());
    // 表达式 import 两目录（各生成 context chunk）
    (globalThis as any).loadModernTemplate = (name: string) =>
      import(`../templates/${name}`);
    (globalThis as any).loadModernWidget = (name: string) =>
      import(`../widgets/${name}`);
  }, []);
  return (
    <main>
      <h1>modernjs home</h1>
    </main>
  );
};

export default Index;
